const cluster = require('node:cluster');
const os = require('node:os');
const http = require('node:http');

if (cluster.isPrimary) {
  // ✅ NEW: fork one worker per CPU core
  for (let i = 0; i < os.cpus().length; i++) {
    cluster.fork(); // ✅ NEW: each worker is a full Node process
  }
  // ✅ NEW: replace crashed workers automatically
  cluster.on('exit', (worker) => {
    console.log(`worker ${worker.process.pid} died, restarting`);
    cluster.fork();
  });
} else {
  // ✅ NEW: workers share the same port via round-robin socket passing
  http.createServer((req, res) => {
    res.end(heavyWork(req.url));
  }).listen(3000);
}

// ⚠️ Workers don't share memory — use Redis/external store for shared
// session/cache state. In-process state (setInterval, in-memory
// caches) is per-worker.
